CardSets.register({"id":"pixar","name":"Pixar Characters","code":"PIXR","description":"Heroes, villains and sidekicks from Pixar — from Woody's roundup to a voyage among the stars.","theme":{"primary":"#2b6cb8","secondary":"#f2c230","artBackground":"#f8f9fa","artFit":"contain"},"pack":{"name":"Pixar Pack","emblem":"⭐","skin":"pixar"},"cards":[{"name":"Woody","rarity":"chase","id":"woody","subtitle":"Toy","details":"Andy's favorite toy and the room's natural leader, a pull-string cowboy whose loyalty is tested when a flashy space ranger arrives.","image":"https://vignette.wikia.nocookie.net/pixar/images/e/ef/Woody_profile.jpg/revision/latest"},{"name":"Buzz Lightyear","rarity":"chase","id":"buzz-lightyear","subtitle":"Toy","details":"A space ranger toy who lands in Andy's room believing he is real, and learns that being a beloved toy is a mission of its own.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/56/Buzz_Profile.jpg/revision/latest"},{"name":"Jessie","rarity":"legendary","id":"jessie","subtitle":"Toy","details":"A rootin'-tootin' cowgirl doll from Woody's Roundup, abandoned by her owner Emily and forever wary of being put back in storage.","image":"https://vignette.wikia.nocookie.net/pixar/images/d/d6/Jessie_Profile.PNG/revision/latest"},{"name":"Bo Peep","rarity":"legendary","id":"bo-peep","subtitle":"Toy","details":"A porcelain shepherdess lamp figure, graceful and sharp, who leaves Andy's house and reinvents herself as a fearless lost-toy rescuer.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/f0/Bo_Peep.png/revision/latest"},{"name":"Forky","rarity":"legendary","id":"forky","subtitle":"Toy","details":"A spork Bonnie crafts into a toy at orientation, who insists he is trash until Woody teaches him what being a toy means.","image":"https://vignette.wikia.nocookie.net/pixar/images/8/8e/Forky.png/revision/latest"},{"name":"Lotso","rarity":"legendary","id":"lotso","subtitle":"Villain","details":"A strawberry-scented bear who runs Sunnyside Daycare like a prison, soured by the day Daisy replaced him and left him behind.","image":"https://vignette.wikia.nocookie.net/pixar/images/1/15/Lotso_Profile.png/revision/latest"},{"name":"Emperor Zurg","rarity":"epic","id":"emperor-zurg","subtitle":"Villain","details":"Buzz Lightyear's sworn enemy and evil emperor of his galaxy, a cape-clad action figure with an ion blaster and a famous secret.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/76/Toy_Story_2_-_Zurg.jpg/revision/latest"},{"name":"Stinky Pete","rarity":"epic","id":"stinky-pete","subtitle":"Villain","details":"The Prospector from Woody's Roundup, mint in his box and bitter about it, determined never to be a forgotten shelf piece.","image":"https://vignette.wikia.nocookie.net/pixar/images/9/91/Stinky_Pete.png/revision/latest"},{"name":"Bullseye","rarity":"rare","id":"bullseye","subtitle":"Toy","details":"Woody's faithful toy horse from the Roundup gang, a wordless puppety steed who gallops to the rescue whenever called.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/72/Bullseye.png/revision/latest"},{"name":"Rex","rarity":"epic","id":"rex","subtitle":"Toy","details":"A plastic Tyrannosaurus terrified of being scary enough, whose tiny arms and big anxieties make him the room's gentle giant.","image":"https://vignette.wikia.nocookie.net/pixar/images/3/39/Rex_Profile.png/revision/latest"},{"name":"Hamm","rarity":"epic","id":"hamm","subtitle":"Toy","details":"A wisecracking piggy bank who treats Andy's room like a casino floor, always ready with a coin, a quip, or a channel flip.","image":"https://vignette.wikia.nocookie.net/pixar/images/8/8d/Hamm_Profile.PNG/revision/latest"},{"name":"Mr. Potato Head","rarity":"epic","id":"mr-potato-head","subtitle":"Toy","details":"A sarcastic spud whose eyes, ears, and mouth pop off at the worst moments, married to his sweetheart Mrs. Potato Head.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/f0/SurprisedMrP_tato.jpg/revision/latest"},{"name":"Slinky Dog","rarity":"rare","id":"slinky-dog","subtitle":"Toy","details":"A dachshund with a metal spring for a middle, loyal to Woody and handy whenever the toys need to stretch across a gap.","image":"https://vignette.wikia.nocookie.net/pixar/images/c/ce/Slinky0002.png/revision/latest"},{"name":"Sid Phillips","rarity":"epic","id":"sid-phillips","subtitle":"Villain","details":"Andy's next-door neighbor, a toy-tormenting kid who straps rockets to action figures until the toys finally teach him a lesson.","image":"https://vignette.wikia.nocookie.net/pixar/images/9/94/Sid-Phillips.png/revision/latest"},{"name":"Gabby Gabby","rarity":"rare","id":"gabby-gabby","subtitle":"Villain","details":"A 1950s pull-string doll in an antique store whose defective voice box drives her scheme to take Woody's own working one.","image":"https://vignette.wikia.nocookie.net/pixar/images/9/93/Gabby_Gabby.jpg/revision/latest"},{"name":"Duke Caboom","rarity":"rare","id":"duke-caboom","subtitle":"Toy","details":"Canada's greatest daredevil toy, a motorcycle stuntman haunted by his TV ad's promises and eager to pose for a comeback.","image":"https://vignette.wikia.nocookie.net/pixar/images/9/96/DukeCaboomFull.JPG/revision/latest"},{"name":"Mrs. Potato Head","rarity":"uncommon","id":"mrs-potato-head","subtitle":"Toy","details":"Mr. Potato Head's beloved wife, packed with spare parts for the whole gang, including an extra eye that sees what others miss.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/a7/BEST_MRS.POTATO_HEAD_EVER.png/revision/latest"},{"name":"Ken","rarity":"rare","id":"ken","subtitle":"Toy","details":"A fashion-obsessed doll living in a Sunnyside dream house, whose romance with Barbie collides with his loyalty to Lotso.","image":"https://vignette.wikia.nocookie.net/pixar/images/1/1f/Ken.jpeg/revision/latest"},{"name":"Barbie","rarity":"uncommon","id":"barbie","subtitle":"Toy","details":"A tour-guide doll from Molly's room who ends up at Sunnyside, where her quick thinking helps the toys stand up to Lotso.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/f8/Barbie_profile.png/revision/latest"},{"name":"Trixie","rarity":"uncommon","id":"trixie","subtitle":"Toy","details":"Bonnie's plastic Triceratops, a cheerful gamer dinosaur who teams up with Rex and frets over her internet know-how.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/f6/Trixie_Triceratops.png/revision/latest"},{"name":"Ducky","rarity":"rare","id":"ducky","subtitle":"Toy","details":"A carnival-prize plush duck fused at the wing to Bunny, forever scheming to finally be won by a kid of their own.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/fa/Ducky_%28Toy_Story_4%29.jpg/revision/latest"},{"name":"Bunny","rarity":"rare","id":"bunny","subtitle":"Toy","details":"A blue-and-green carnival plush bunny attached to Ducky, dreaming up wild plush-rush plans to escape the prize wall.","image":"https://vignette.wikia.nocookie.net/pixar/images/e/e1/Bunny_%28Toy_Story_4%29.jpg/revision/latest"},{"name":"Sox","rarity":"rare","id":"sox","subtitle":"Robot","details":"A robotic therapy cat assigned to Buzz in Lightyear, a calm, sarcastic companion who can solve hyperspace math in his sleep.","image":"https://vignette.wikia.nocookie.net/pixar/images/e/e3/Sox_transparent.png/revision/latest"},{"name":"Andy Davis","rarity":"uncommon","id":"andy-davis","subtitle":"Human","details":"The boy whose imagination brings the whole room to life, and whose name is written on the bottom of Woody's boot.","image":"https://vignette.wikia.nocookie.net/pixar/images/e/ed/Andy.webp/revision/latest"},{"name":"Bonnie Anderson","rarity":"uncommon","id":"bonnie-anderson","subtitle":"Human","details":"The imaginative kindergartner who inherits Andy's toys and crafts Forky, giving the old gang a second childhood to serve.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/44/Bonnie_TS5.png/revision/latest"},{"name":"Al McWhiggin","rarity":"uncommon","id":"al-mcwhiggin","subtitle":"Villain","details":"The greedy toy collector of Al's Toy Barn, who spots Woody at a yard sale and steals him to complete a museum-bound set.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/4c/Toy_Story_2_-_Al_talking_on_phone.webp/revision/latest"},{"name":"Benson","rarity":"uncommon","id":"benson","subtitle":"Villain","details":"A silent ventriloquist dummy who leads Gabby Gabby's henchmen in the antique store, gliding about on unnerving little wheels.","image":"https://vignette.wikia.nocookie.net/pixar/images/6/6d/Screen_Shot_2019-05-13_at_11.19.35_PM.png/revision/latest"},{"name":"Buttercup","rarity":"uncommon","id":"buttercup","subtitle":"Toy","details":"Bonnie's plush unicorn, a deadpan toy-room regular whose dry one-liners undercut every dramatic moment in Bonnie's games.","image":"https://vignette.wikia.nocookie.net/pixar/images/c/c6/Buttercup.png/revision/latest"},{"name":"Dolly","rarity":"uncommon","id":"dolly","subtitle":"Toy","details":"Bonnie's soft rag doll and unofficial leader of her toy room, a welcoming face for every newcomer Andy's gang meets.","image":"https://vignette.wikia.nocookie.net/pixar/images/d/da/Dolly_Promo.jpg/revision/latest"},{"name":"Mr. Pricklepants","rarity":"uncommon","id":"mr-pricklepants","subtitle":"Toy","details":"Bonnie's lederhosen-wearing hedgehog thespian, who treats every playtime like serious theatre and corrects the staging.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/5d/Mr._Pricklepants.png/revision/latest"},{"name":"Giggle McDimples","rarity":"common","id":"giggle-mcdimples","subtitle":"Toy","details":"A tiny plastic police officer from a miniature playset, Bo Peep's confident little partner in lost-toy rescues.","image":"https://vignette.wikia.nocookie.net/disney/images/6/6f/Profile_Giggle_McDimples.jpg/revision/latest"},{"name":"Combat Carl","rarity":"common","id":"combat-carl","subtitle":"Toy","details":"A soldier action figure who has seen things at the highway rest stop, warning lost toys about the dangers of the road.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/5c/Toy-Story-of-Terror-Combat-Carl.jpg/revision/latest"},{"name":"Izzy Hawthorne","rarity":"uncommon","id":"izzy-hawthorne","subtitle":"Heroine","details":"A determined junior space ranger in Lightyear, granddaughter of Buzz's commander, who refuses to let her planet stay stranded.","image":"https://vignette.wikia.nocookie.net/pixar/images/e/eb/Izzy_Hawthorne_render.jpeg/revision/latest"},{"name":"Alisha Hawthorne","rarity":"uncommon","id":"alisha-hawthorne","subtitle":"Heroine","details":"Buzz's commanding officer and best friend in Lightyear, whose life unfolds across the years his time-dilated flights skip past.","image":"https://vignette.wikia.nocookie.net/pixar/images/e/e0/Alisha_Hawthorne_render.jpeg/revision/latest"},{"name":"Hannah Phillips","rarity":"common","id":"hannah-phillips","subtitle":"Human","details":"Sid's little sister, whose tea parties feature her brother's mutated toys, including a doll head on a pterodactyl body.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/4e/Hannah_Phillips.jpg/revision/latest"},{"name":"Scud","rarity":"common","id":"scud","subtitle":"Animal","details":"Sid Phillips' bull terrier, the terror of the toy world, whose jaws end more than one daring escape across the hallway.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/57/Scud1.jpg/revision/latest"},{"name":"Wheezy","rarity":"common","id":"wheezy","subtitle":"Toy","details":"A squeaky penguin toy shelved with a broken squeaker, rescued from a yard sale by Woody's riskiest mission in Toy Story 2.","image":"https://vignette.wikia.nocookie.net/pixar/images/1/15/Wheezy_Profile.PNG/revision/latest"},{"name":"Sarge","rarity":"common","id":"sarge","subtitle":"Toy","details":"The green army men's no-nonsense leader, a toy soldier who runs reconnaissance from the houseplant with binoculars and grit.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/a3/Sarge_Toy.webp/revision/latest"},{"name":"RC","rarity":"common","id":"rc","subtitle":"Toy","details":"Andy's remote-control car, the toys' fastest wheels, steered into rescues from moving trucks to runaway playrooms.","image":"https://vignette.wikia.nocookie.net/pixar/images/c/cd/RC_png.png/revision/latest"},{"name":"Lenny","rarity":"common","id":"lenny","subtitle":"Toy","details":"A pair of wind-up binoculars on legs, the toy room's lookout who spots trouble long before anyone else can see it.","image":"https://vignette.wikia.nocookie.net/pixar/images/8/88/Lenny.webp/revision/latest"},{"name":"Etch","rarity":"common","id":"etch","subtitle":"Toy","details":"An Etch A Sketch with lightning knobs, able to draw a perfect map, portrait, or wanted poster in a matter of seconds.","image":"https://vignette.wikia.nocookie.net/pixar/images/8/88/Profile_-_Etch_A_Sketch.webp/revision/latest"},{"name":"Rocky Gibraltar","rarity":"common","id":"rocky-gibraltar","subtitle":"Toy","details":"A hulking toy wrestler in Andy's room, strong, silent, and ready to toss intruders or furniture with equal ease.","image":"https://vignette.wikia.nocookie.net/pixar/images/3/38/Rocky_Gibraltar.webp/revision/latest"},{"name":"Chuckles","rarity":"common","id":"chuckles","subtitle":"Toy","details":"A glum clown toy from Daisy and Lotso's past, whose sad story of being lost and replaced explains the bear's bitterness.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/5d/Chuckles_Clown.jpg/revision/latest"},{"name":"Peas-in-a-Pod","rarity":"common","id":"peas-in-a-pod","subtitle":"Toy","details":"Three smiling plush peas zipped inside a fuzzy pod, Bonnie's tiniest toys, forever bouncing around as one unit.","image":"https://vignette.wikia.nocookie.net/pixar/images/2/2e/Peas-in-a-Pod.png/revision/latest"},{"name":"Big Baby","rarity":"common","id":"big-baby","subtitle":"Toy","details":"A huge, silent baby doll at Sunnyside with one lazy eye, Lotso's enforcer who still wears the locket Daisy gave him.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/4c/Big_Baby.jpg/revision/latest"},{"name":"Billy, Goat, and Gruff","rarity":"common","id":"billy-goat-and-gruff","subtitle":"Toy","details":"Bo Peep's three-headed porcelain sheep, a mischievous little flock that rides her crook into every lost-toy rescue.","image":"https://vignette.wikia.nocookie.net/pixar/images/c/c4/Bo_Peep%27s_sheep.webp/revision/latest"},{"name":"Margaret","rarity":"common","id":"margaret","subtitle":"Human","details":"The patient owner of Second Chance Antiques, the shop where Woody reunites with Bo Peep among shelves of forgotten toys.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/45/Screen_Shot_2019-06-21_at_6.55.08_PM.png/revision/latest"},{"name":"Mo Morrison","rarity":"common","id":"mo-morrison","subtitle":"Sidekick","details":"A cheerful rookie ranger in Lightyear, part of Buzz's small crew, whose optimism survives every disaster on T'Kani Prime.","image":"https://vignette.wikia.nocookie.net/pixar/images/6/66/Mo_Morrison_render.jpeg/revision/latest"},{"name":"Darby Steel","rarity":"common","id":"darby-steel","subtitle":"Sidekick","details":"The oldest recruit on Buzz's Lightyear crew, a seasoned ranger whose steady nerves balance out the rookies around her.","image":"https://vignette.wikia.nocookie.net/disney/images/2/24/Profile_-_Steel.jpg/revision/latest"},{"name":"Commander Burnside","rarity":"common","id":"commander-burnside","subtitle":"Villain","details":"The stern commander in Lightyear who grounds Buzz's squadron and orders the colony to make its home on T'Kani Prime.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/a5/Commander2_burnside.png/revision/latest"},{"name":"Featheringhamstan","rarity":"common","id":"featheringhamstan","subtitle":"Sidekick","details":"A cat-like alien hatchling Buzz's crew adopts in Lightyear, named on the spot and carried through their jungle trek.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/ac/Featheringhamsten.png/revision/latest"},{"name":"Geri","rarity":"common","id":"geri","subtitle":"Human","details":"The toy cleaner who restores Woody to mint condition in Toy Story 2, the same white-bearded man who plays chess alone in Geri's Game.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/fd/Geri%27s_Game-_Geri_full.png/revision/latest"},{"name":"Flik","rarity":"legendary","id":"flik","subtitle":"Hero","details":"An inventive ant whose harvester mishap brings the circus bugs to Ant Island as pretend warriors against the grasshoppers.","image":"https://vignette.wikia.nocookie.net/pixar/images/e/e5/Profile_-_Flik.webp/revision/latest"},{"name":"Hopper","rarity":"legendary","id":"hopper","subtitle":"Villain","details":"The scarred grasshopper gang leader who bullies Ant Island for food and teaches his brother Molt to fear the birds.","image":"https://vignette.wikia.nocookie.net/pixar/images/8/81/Hopper.png/revision/latest"},{"name":"Princess Atta","rarity":"epic","id":"princess-atta","subtitle":"Insect","details":"The anxious crown princess of the ant colony, a perfectionist learning to lead under her mother's watchful eye.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/78/Profile_-_Atta.webp/revision/latest"},{"name":"Dot","rarity":"rare","id":"dot","subtitle":"Insect","details":"Flik's biggest fan, a small blueberry-scout ant princess who believes in him when the whole colony doubts his ideas.","image":"https://vignette.wikia.nocookie.net/pixar/images/6/62/Profile-_Dot.webp/revision/latest"},{"name":"Heimlich","rarity":"epic","id":"heimlich","subtitle":"Insect","details":"A plump green caterpillar circus clown who dreams of becoming a beautiful butterfly and snacks through every crisis.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/59/Heimlich_screaming.jpg/revision/latest"},{"name":"Francis","rarity":"rare","id":"francis","subtitle":"Insect","details":"A gruff male ladybug constantly mistaken for a girl, whose circus clown act hides a soft spot for the Blueberries.","image":"https://vignette.wikia.nocookie.net/pixar/images/2/22/Bugs-life-disneyscreencaps.com-3409.jpg/revision/latest"},{"name":"Manny","rarity":"uncommon","id":"manny","subtitle":"Insect","details":"A dramatic praying mantis magician whose 'Chinese cabinet of metamorphosis' act headlines P.T. Flea's circus show.","image":"https://vignette.wikia.nocookie.net/pixar/images/0/0c/Manny.jpg/revision/latest"},{"name":"Gypsy","rarity":"uncommon","id":"gypsy","subtitle":"Insect","details":"A graceful moth and Manny's stage partner, whose shimmering wings sell every illusion in the circus bugs' traveling act.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/73/Gypsy_the_Moth_%28A_Bug%27s_Life%29.png/revision/latest"},{"name":"Slim","rarity":"uncommon","id":"slim","subtitle":"Insect","details":"A lanky stick insect clown who is forever cast as a prop, a broom, or a bridge in the circus bugs' slapstick routines.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/47/Slimbugslife.png/revision/latest"},{"name":"Rosie","rarity":"uncommon","id":"rosie","subtitle":"Animal","details":"A black widow spider who wrangles the circus troupe's unruly acts with a whip and a mother's patience.","image":"https://vignette.wikia.nocookie.net/pixar/images/c/cd/Screenshot_2026-09-08_at_17-56-26_EKPYkd7UcAQG0l8_%28WEBP_Image_1200_%C3%97_509_pixels%29_%E2%80%94_Scaled_%2898%25%29.png/revision/latest"},{"name":"Dim","rarity":"rare","id":"dim","subtitle":"Animal","details":"A huge blue rhinoceros beetle with a gentle heart, the circus strongman who turns timid until someone threatens Rosie.","image":"https://vignette.wikia.nocookie.net/pixar/images/3/3c/Dimbugslife.jpg/revision/latest"},{"name":"Molt","rarity":"uncommon","id":"molt","subtitle":"Insect","details":"Hopper's talkative younger brother, a grasshopper mid-molt whose chatter earns him threats from the whole gang.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/4e/Molt.png/revision/latest"},{"name":"P.T. Flea","rarity":"common","id":"pt-flea","subtitle":"Insect","details":"The ringmaster of the flea circus, a showman whose flaming finale spectacularly burns down his own big top.","image":"https://vignette.wikia.nocookie.net/pixar/images/d/d5/Screenshot_2026-09-08_at_22-17-05_EKPYm1aUcAUNymd_%28WEBP_Image_1200_%C3%97_510_pixels%29_%E2%80%94_Scaled_%2898%25%29.png/revision/latest"},{"name":"The Queen","rarity":"common","id":"the-queen","subtitle":"Insect","details":"The elderly ant queen of the colony, Atta and Dot's mother, who carries her pet aphid Aphie everywhere she goes.","image":"https://vignette.wikia.nocookie.net/pixar/images/6/64/Queen.jpg/revision/latest"},{"name":"Tuck","rarity":"uncommon","id":"tuck","subtitle":"Insect","details":"One half of a Hungarian pill-bug duo in the circus, a tumbling clown whose act with Roll needs no shared language.","image":"https://vignette.wikia.nocookie.net/pixar/images/d/d2/Bugs-life-disneyscreencaps.com-3353.jpg/revision/latest"},{"name":"Roll","rarity":"uncommon","id":"roll","subtitle":"Insect","details":"The other half of the pill-bug clown duo, a roly-poly acrobat who argues with Tuck in cheerful gibberish mid-performance.","image":"https://vignette.wikia.nocookie.net/pixar/images/d/d2/Bugs-life-disneyscreencaps.com-3353.jpg/revision/latest"},{"name":"Mr. Soil","rarity":"common","id":"mr-soil","subtitle":"Insect","details":"The colony's resident thespian, an ant who stages the colony's dramatic mural play recounting its battles each season.","image":"https://vignette.wikia.nocookie.net/pixar/images/2/28/Soil.jpg/revision/latest"},{"name":"Dr. Flora","rarity":"common","id":"dr-flora","subtitle":"Insect","details":"Ant Island's kindly doctor, a pill-bug-like ant who tends the colony's bumps and bruises between harvest crises.","image":"https://vignette.wikia.nocookie.net/pixar/images/d/d4/Flora.jpg/revision/latest"},{"name":"Thorny","rarity":"common","id":"thorny","subtitle":"Insect","details":"A grumpy elder ant on the colony council, quick to doubt Flik's inventions and slow to admit when they work.","image":"https://vignette.wikia.nocookie.net/pixar/images/8/86/Thorny.jpg/revision/latest"},{"name":"Cornelius","rarity":"common","id":"cornelius","subtitle":"Insect","details":"An elderly ant leaning on a walking stick, one of the colony's oldest voices at council gatherings on Ant Island.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/a3/Cornelius.jpg/revision/latest"},{"name":"Aphie","rarity":"common","id":"aphie","subtitle":"Animal","details":"The Queen's pampered pet aphid, a tiny green companion carried in her arms like a lapdog wherever the court goes.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/55/Aphie.jpg/revision/latest"},{"name":"Thumper","rarity":"common","id":"thumper","subtitle":"Insect","details":"Hopper's feral pet grasshopper, kept on a chain and sicced on anyone who needs reminding why the ants pay tribute.","image":"https://vignette.wikia.nocookie.net/pixar/images/8/81/Thumper.png/revision/latest"},{"name":"Sulley","rarity":"chase","id":"sulley","subtitle":"Monster","details":"Monsters, Inc.'s top scarer, a huge blue-furred softie whose career changes forever when a human toddler calls him Kitty.","image":"https://vignette.wikia.nocookie.net/pixar/images/e/e7/SulleyMAW.png/revision/latest"},{"name":"Mike Wazowski","rarity":"chase","id":"mike-wazowski","subtitle":"Monster","details":"Sulley's one-eyed best friend and scare-floor wrangler, a fast-talking green comedian who dreams of the company spotlight.","image":"https://vignette.wikia.nocookie.net/pixar/images/9/96/MikeMAW.png/revision/latest"},{"name":"Randall Boggs","rarity":"legendary","id":"randall-boggs","subtitle":"Villain","details":"A slithering, chameleon-like scarer who can vanish at will and plots to kidnap children to solve the city's energy crisis.","image":"https://vignette.wikia.nocookie.net/pixar/images/0/09/Randall_Boggs.png/revision/latest"},{"name":"Boo","rarity":"legendary","id":"boo","subtitle":"Heroine","details":"The fearless toddler who slips into Monstropolis in a monster costume and melts the hearts of its two biggest scarers.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/7c/Boo.png/revision/latest"},{"name":"Henry J. Waternoose","rarity":"epic","id":"henry-j-waternoose","subtitle":"Villain","details":"The crab-like CEO of Monsters, Inc., whose grandfatherly warmth hides a willingness to kidnap a thousand children.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/51/Henry_J._Waternoose_III.jpg/revision/latest"},{"name":"Roz","rarity":"rare","id":"roz","subtitle":"Monster","details":"The slug-like dispatch master of Scare Floor F, whose drawling reminders about paperwork always arrive one step ahead.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/f3/Roz1.jpg/revision/latest"},{"name":"Celia Mae","rarity":"rare","id":"celia-mae","subtitle":"Monster","details":"Mike's one-eyed, snake-haired girlfriend, a Monsters, Inc. receptionist who believes in him until the evidence piles up.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/55/Celia_Mae.png/revision/latest"},{"name":"Fungus","rarity":"uncommon","id":"fungus","subtitle":"Sidekick","details":"Randall's nervous three-eyed assistant, a reluctant accomplice who would rather be anywhere than near the scream extractor.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/50/Fungus.png/revision/latest"},{"name":"Dean Hardscrabble","rarity":"uncommon","id":"dean-hardscrabble","subtitle":"Monster","details":"Monsters University's legendary scarer-turned-dean, a dragon-centipede headmistress no student dares disappoint twice.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/5f/MU-Dean_Hardscrabble.png/revision/latest"},{"name":"George Sanderson","rarity":"common","id":"george-sanderson","subtitle":"Monster","details":"A shaggy orange scarer whose every shift ends in a 2319 decontamination after some child's sock or toy touches him.","image":"https://vignette.wikia.nocookie.net/pixar/images/b/b9/George_Sanderson.jpg/revision/latest"},{"name":"Yeti","rarity":"uncommon","id":"yeti","subtitle":"Monster","details":"The Abominable Snowman, a banished monster in the Himalayas who greets exiles with snow cones and dreams of mail work.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/7d/Yeti.png/revision/latest"},{"name":"Don Carlton","rarity":"uncommon","id":"don-carlton","subtitle":"Monster","details":"A middle-aged salesmonster turned Oozma Kappa founder, a tentacled mature student whose optimism holds the fraternity together.","image":"https://vignette.wikia.nocookie.net/pixar/images/0/03/MU-Don_Carlton.png/revision/latest"},{"name":"Scott Squibbles","rarity":"uncommon","id":"scott-squibbles","subtitle":"Monster","details":"A five-eyed, ever-cheerful Oozma Kappa monster who lives with his mother and believes his team can do anything.","image":"https://vignette.wikia.nocookie.net/pixar/images/d/d6/MU-Scott_Squibbles.png/revision/latest"},{"name":"Terri and Terry Perry","rarity":"uncommon","id":"terri-and-terry-perry","subtitle":"Monster","details":"A two-headed Oozma Kappa pair sharing one body, brothers who bicker and finish each other's sentences in stereo.","image":"https://vignette.wikia.nocookie.net/pixar/images/b/b7/MU-Terri_and_Terry.png/revision/latest"},{"name":"Art","rarity":"uncommon","id":"art","subtitle":"Monster","details":"A fuzzy purple Oozma Kappa monster with a mysterious past, whose free spirit and short legs belie surprising agility.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/5f/ArtMU.jpg/revision/latest"},{"name":"Johnny Worthington III","rarity":"uncommon","id":"johnny-worthington-iii","subtitle":"Monster","details":"The smug president of Roar Omega Roar, a horned fraternity star who underestimates the Oozma Kappas at his peril.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/af/Johnny_Worthington_III.png/revision/latest"},{"name":"Professor Knight","rarity":"common","id":"professor-knight","subtitle":"Monster","details":"The Monsters University scaring professor whose classroom demonstrations sort the fearsome from the forgotten.","image":"https://vignette.wikia.nocookie.net/pixar/images/0/0f/MU-Professor_Knight.jpg/revision/latest"},{"name":"Needleman","rarity":"common","id":"needleman","subtitle":"Monster","details":"A skinny Monsters, Inc. janitor, half of a two-monster cleanup crew forever mopping up after the scare floors.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/f4/Needleman_%26_Smitty.png/revision/latest"},{"name":"Smitty","rarity":"common","id":"smitty","subtitle":"Monster","details":"Needleman's stocky janitor partner at Monsters, Inc., equally baffled by every strange event on the factory floor.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/f4/Needleman_%26_Smitty.png/revision/latest"},{"name":"Charlie Proctor","rarity":"common","id":"charlie-proctor","subtitle":"Monster","details":"George Sanderson's put-upon scare assistant, a two-eyed monster always one accident away from another 2319 alarm.","image":"https://vignette.wikia.nocookie.net/pixar/images/9/97/Charlie_Proctor.png/revision/latest"},{"name":"Jerry Slugworth","rarity":"common","id":"jerry-slugworth","subtitle":"Monster","details":"The genial slug-like scare floor manager at Monsters, Inc., who keeps the leaderboards and the door lines moving.","image":"https://vignette.wikia.nocookie.net/pixar/images/0/00/Jerry_MonstersInc.jpg/revision/latest"},{"name":"Waxford","rarity":"common","id":"waxford","subtitle":"Monster","details":"A many-eyed Monsters, Inc. employee whose gaze covers the whole floor, impossible to sneak a human child past.","image":"https://vignette.wikia.nocookie.net/pixar/images/0/0d/Waxford.png/revision/latest"},{"name":"Frank McCay","rarity":"common","id":"frank-mccay","subtitle":"Monster","details":"A Monsters University alumnus scarer whose trading card inspires young Mike Wazowski to chase the scare program.","image":"https://vignette.wikia.nocookie.net/pixar/images/1/1d/Die_monster_uni_frank_mccay.jpg/revision/latest"},{"name":"Brock Pearson","rarity":"common","id":"brock-pearson","subtitle":"Monster","details":"A sporty, sharp-beaked Monsters University student who co-hosts the Scare Games with unshakeable fraternity pride.","image":"https://vignette.wikia.nocookie.net/pixar/images/1/1e/MU-Brock_Pearson.jpg/revision/latest"},{"name":"Claire Wheeler","rarity":"common","id":"claire-wheeler","subtitle":"Monster","details":"The deadpan president of the Greek Council at Monsters University, who runs the Scare Games with icy precision.","image":"https://vignette.wikia.nocookie.net/pixar/images/6/6e/MU-Greek-Council-Claire-Crop.jpg/revision/latest"},{"name":"Carrie Williams","rarity":"common","id":"carrie-williams","subtitle":"Monster","details":"The president of Python Nu Kappa, the Scare Games' most intimidating sorority, all pink fur and cutting smiles.","image":"https://vignette.wikia.nocookie.net/pixar/images/d/da/Carrie_williams_crop_poster.jpg/revision/latest"},{"name":"Javier Rios","rarity":"common","id":"javier-rios","subtitle":"Monster","details":"A four-armed Roar Omega Roar monster at Monsters University, one of Johnny Worthington's elite scare teammates.","image":"https://vignette.wikia.nocookie.net/pixar/images/0/0d/Javier_Rios.jpg/revision/latest"},{"name":"Reggie Jacobs","rarity":"common","id":"reggie-jacobs","subtitle":"Monster","details":"A slug-like Roar Omega Roar member at Monsters University, slow of body and sharp of tongue in the Scare Games.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/fc/Reggie_Jacobs.jpg/revision/latest"},{"name":"Sherri Squibbles","rarity":"common","id":"sherri-squibbles","subtitle":"Monster","details":"Scott 'Squishy' Squibbles' mother, who rents her house to Oozma Kappa and cheers the boys on at full volume.","image":"https://vignette.wikia.nocookie.net/pixar/images/c/cf/MU-Sheri_Squibbles.jpg/revision/latest"},{"name":"Nemo","rarity":"chase","id":"nemo","subtitle":"Fish","details":"A young clownfish with a small lucky fin, whose capture by a diver sends his father across the entire ocean to find him.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/aa/Nemo-FN.png/revision/latest"},{"name":"Dory","rarity":"chase","id":"dory","subtitle":"Fish","details":"A cheerful blue tang with short-term memory loss who just keeps swimming, and whose heart guides two rescue journeys.","image":"https://vignette.wikia.nocookie.net/pixar/images/1/1f/Dory-white.jpg/revision/latest"},{"name":"Marlin","rarity":"legendary","id":"marlin","subtitle":"Fish","details":"Nemo's anxious clownfish father, who crosses sharks, jellyfish, and the East Australian Current to bring his son home.","image":"https://vignette.wikia.nocookie.net/pixar/images/d/d9/Marlin.png/revision/latest"},{"name":"Hank","rarity":"legendary","id":"hank","subtitle":"Animal","details":"A gruff seven-tentacled octopus at the marine life institute, a camouflage master who helps Dory in exchange for a tag.","image":"https://vignette.wikia.nocookie.net/pixar/images/d/de/Hank_FD.jpg/revision/latest"},{"name":"Gill","rarity":"rare","id":"gill","subtitle":"Fish","details":"The scarred Moorish idol leading the dentist's tank gang, a wild-caught dreamer who plans every escape down to the pebble.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/72/Gill.png/revision/latest"},{"name":"Crush","rarity":"epic","id":"crush","subtitle":"Animal","details":"A 150-year-old sea turtle who rides the East Australian Current like a surfer and teaches Marlin to let go a little.","image":"https://vignette.wikia.nocookie.net/disney/images/1/19/Profile_-_Crush.jpg/revision/latest"},{"name":"Bruce","rarity":"epic","id":"bruce","subtitle":"Fish","details":"A great white shark running a support group for reformed fish-eaters, whose motto is that fish are friends, not food.","image":"https://vignette.wikia.nocookie.net/disney/images/d/d3/Profile_-_Bruce.jpg/revision/latest"},{"name":"Destiny","rarity":"rare","id":"destiny","subtitle":"Fish","details":"A near-sighted whale shark at the marine life institute, Dory's childhood pipe-pal who swims into walls with good cheer.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/41/Destiny_FD.jpg/revision/latest"},{"name":"Bailey","rarity":"rare","id":"bailey","subtitle":"Animal","details":"A beluga whale at the institute convinced his echolocation is broken, whose sonar finally saves the day in the open bay.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/7d/Bailey_FD.jpg/revision/latest"},{"name":"Mr. Ray","rarity":"uncommon","id":"mr-ray","subtitle":"Fish","details":"The spotted eagle ray schoolteacher who ferries the reef's children on his back, singing science into every lesson.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/58/MrRay.jpg/revision/latest"},{"name":"Squirt","rarity":"uncommon","id":"squirt","subtitle":"Animal","details":"Crush's tiny turtle hatchling, a fearless little rider separated from the current and thrilled by every second of it.","image":"https://vignette.wikia.nocookie.net/pixar/images/b/b4/Squirt.png/revision/latest"},{"name":"Nigel","rarity":"uncommon","id":"nigel","subtitle":"Animal","details":"A pelican who ferries news between Sydney Harbour and the dentist's tank, forever dodging seagulls crying 'Mine!'","image":"https://vignette.wikia.nocookie.net/pixar/images/d/d9/Finding_Nemo_Nigel.png/revision/latest"},{"name":"Darla Sherman","rarity":"rare","id":"darla-sherman","subtitle":"Villain","details":"The dentist's braces-wearing niece, a notorious fish-shaker whose arrival in the office terrifies every tank resident.","image":"https://vignette.wikia.nocookie.net/pixar/images/0/01/Darla-Sherman.png/revision/latest"},{"name":"Bloat","rarity":"uncommon","id":"bloat","subtitle":"Fish","details":"A porcupinefish in the tank gang who puffs up whenever he is stressed, surprised, or simply addressed too suddenly.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/5b/Bloat_finding_nemo.png/revision/latest"},{"name":"Peach","rarity":"uncommon","id":"peach","subtitle":"Animal","details":"A pink starfish stuck to the tank glass, the gang's lookout who reports every move the dentist makes outside the glass.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/74/Peach_Close_Up.jpg/revision/latest"},{"name":"Gurgle","rarity":"uncommon","id":"gurgle","subtitle":"Fish","details":"The tank gang's germophobic royal gramma, a purple fish who dreams of an origin story and dreads the dirty tank water.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/fb/Gurgle_3.jpg/revision/latest"},{"name":"Deb","rarity":"uncommon","id":"deb","subtitle":"Fish","details":"A damselfish who believes her reflection is her twin sister Flo, chatting with the glass through every tank crisis.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/79/Deb1.png/revision/latest"},{"name":"Jacques","rarity":"uncommon","id":"jacques","subtitle":"Animal","details":"A French cleaner shrimp who keeps the tank spotless, polishing ornaments and fellow residents with equal devotion.","image":"https://vignette.wikia.nocookie.net/pixar/images/d/d5/Jacques.jpg/revision/latest"},{"name":"Bubbles","rarity":"common","id":"bubbles","subtitle":"Fish","details":"A yellow tang obsessed with the tank's treasure chest, crying 'Bubbles!' whenever it opens and releases its stream.","image":"https://vignette.wikia.nocookie.net/pixar/images/0/0c/Bubbles.png/revision/latest"},{"name":"Anchor","rarity":"uncommon","id":"anchor","subtitle":"Fish","details":"A hammerhead shark in Bruce's support group, a reformed fish-eater who hauls Chum back whenever the meetings wobble.","image":"https://vignette.wikia.nocookie.net/disney/images/0/04/Finding_Nemo_-_Anchor_profile.png/revision/latest"},{"name":"Chum","rarity":"uncommon","id":"chum","subtitle":"Fish","details":"A mako shark in the support group, whose enthusiasm for the pledge tests every meeting Bruce tries to hold.","image":"https://vignette.wikia.nocookie.net/disney/images/a/aa/Profile_-_Chum.jpg/revision/latest"},{"name":"Coral","rarity":"common","id":"coral","subtitle":"Fish","details":"Marlin's mate and Nemo's mother, lost to a barracuda attack on the family's new anemone home at the drop-off's edge.","image":"https://vignette.wikia.nocookie.net/pixar/images/2/2d/Coral-the-Clownfish.png/revision/latest"},{"name":"Jenny","rarity":"uncommon","id":"jenny","subtitle":"Fish","details":"Dory's loving mother, who builds shell paths at the institute so her forgetful daughter can always find her way home.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/43/Finding_Dory_Jenny.png/revision/latest"},{"name":"Charlie","rarity":"uncommon","id":"charlie","subtitle":"Fish","details":"Dory's father, whose patient games of hide-and-seek taught his daughter the skills she uses to find her family again.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/74/Finding_Dory_Charlie.png/revision/latest"},{"name":"Becky","rarity":"common","id":"becky","subtitle":"Animal","details":"A loopy common loon who ferries Hank and a cup of Dory across the institute grounds without a single word spoken.","image":"https://vignette.wikia.nocookie.net/pixar/images/1/19/Loon_FD.jpg/revision/latest"},{"name":"Gerald","rarity":"common","id":"gerald","subtitle":"Animal","details":"A sea lion forever shooed off the prime sunning rock by Fluke and Rudder, sneaking back whenever they fall asleep.","image":"https://vignette.wikia.nocookie.net/pixar/images/6/6c/Gerald_Sea_Lion.png/revision/latest"},{"name":"Fluke","rarity":"common","id":"fluke","subtitle":"Animal","details":"One of two sea lions lounging on the institute's best rock, a champion napper voiced with Rudder as the local welcoming party.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/77/Fluke_and_Rudder.jpg/revision/latest"},{"name":"Rudder","rarity":"common","id":"rudder","subtitle":"Animal","details":"Fluke's fellow sea lion rock-owner, quick with a bark at Gerald and quicker still to drift back to sleep in the sun.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/77/Fluke_and_Rudder.jpg/revision/latest"},{"name":"Sheldon","rarity":"common","id":"sheldon","subtitle":"Fish","details":"A young seahorse in Mr. Ray's class, allergic to water in a way that makes every school excursion a sneezing hazard.","image":"https://vignette.wikia.nocookie.net/pixar/images/3/31/Sheldon.jpg/revision/latest"},{"name":"Tad","rarity":"common","id":"tad","subtitle":"Fish","details":"A young butterfly fish in Mr. Ray's class, Nemo's bold schoolmate on his first day at the drop-off.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/a9/Tad.jpg/revision/latest"},{"name":"Pearl","rarity":"common","id":"pearl","subtitle":"Animal","details":"A tiny flapjack octopus in Mr. Ray's class who inks herself at the slightest startle, Nemo's shy school friend.","image":"https://vignette.wikia.nocookie.net/pixar/images/e/eb/Pearl.jpg/revision/latest"},{"name":"Mr. Incredible","rarity":"chase","id":"mr-incredible","subtitle":"Hero","details":"Bob Parr, a super-strong hero forced into suburban hiding, whose secret return to hero work puts his whole family at risk.","image":"https://vignette.wikia.nocookie.net/disney/images/d/d2/Profile_-_Bob_Parr.jpeg/revision/latest"},{"name":"Elastigirl","rarity":"legendary","id":"elastigirl","subtitle":"Heroine","details":"Helen Parr, who stretches into any shape and holds her family together, on the ground and in the middle of a supervillain plot.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/f3/Elastigirl_Transparent.webp/revision/latest"},{"name":"Edna Mode","rarity":"legendary","id":"edna-mode","subtitle":"Sidekick","details":"The tiny, imperious designer of superhero suits, whose golden rule for every hero she dresses is simple: no capes.","image":"https://vignette.wikia.nocookie.net/pixar/images/8/8b/I2_-_Edna.png/revision/latest"},{"name":"Syndrome","rarity":"legendary","id":"syndrome","subtitle":"Villain","details":"Buddy Pine, Mr. Incredible's rejected fanboy, who grows up to invent his own powers and stage himself as a hero.","image":"https://vignette.wikia.nocookie.net/pixar/images/b/b3/Syndrome.png/revision/latest"},{"name":"Violet Parr","rarity":"epic","id":"violet-parr","subtitle":"Heroine","details":"The Parrs' shy teenage daughter, who turns invisible and projects force fields, gaining confidence along with control.","image":"https://vignette.wikia.nocookie.net/disney/images/e/e0/Profile_-_Violet_Parr.jpeg/revision/latest"},{"name":"Dash Parr","rarity":"epic","id":"dash-parr","subtitle":"Hero","details":"The Parrs' ten-year-old speedster, forever restrained from sports because no race against him could ever be fair.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/a5/I2_-_Dash.png/revision/latest"},{"name":"Frozone","rarity":"epic","id":"frozone","subtitle":"Hero","details":"Lucius Best, Bob's ice-slinging best friend, whose super suit is always exactly where his wife Honey says it is not.","image":"https://vignette.wikia.nocookie.net/pixar/images/e/ed/I2_-_Frozone_2.png/revision/latest"},{"name":"Jack-Jack Parr","rarity":"uncommon","id":"jack-jack-parr","subtitle":"Hero","details":"The Parr baby whose bursting catalogue of powers, from laser eyes to multiplying, overwhelms every sitter he meets.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/41/I2_-_Jack-Jack.png/revision/latest"},{"name":"Mirage","rarity":"uncommon","id":"mirage","subtitle":"Sidekick","details":"Syndrome's elegant right hand, whose conscience turns when she learns his island games are killing real heroes.","image":"https://vignette.wikia.nocookie.net/pixar/images/b/b8/Mirage1.jpg/revision/latest"},{"name":"Evelyn Deavor","rarity":"rare","id":"evelyn-deavor","subtitle":"Villain","details":"The Screenslaver behind the scenes, a tech heiress who hypnotizes heroes through screens to keep them outlawed forever.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/a8/Evelyn_Deavor.png/revision/latest"},{"name":"Winston Deavor","rarity":"uncommon","id":"winston-deavor","subtitle":"Hero","details":"A telecom magnate and superhero superfan who campaigns to legalize heroes again, fronting the cost and the cameras.","image":"https://vignette.wikia.nocookie.net/pixar/images/3/31/Pixar_INC2_Winston_Deavor.png/revision/latest"},{"name":"Bomb Voyage","rarity":"uncommon","id":"bomb-voyage","subtitle":"Villain","details":"A French mime-themed villain robbing a bank with explosives, interrupted the night young Buddy Pine begs to help.","image":"https://vignette.wikia.nocookie.net/pixar/images/e/e1/Bomb_Voyage.png/revision/latest"},{"name":"The Underminer","rarity":"uncommon","id":"the-underminer","subtitle":"Villain","details":"A mole-like villain who bursts from beneath the city streets declaring war on peace and happiness above ground.","image":"https://vignette.wikia.nocookie.net/pixar/images/3/39/The_Underminer.png/revision/latest"},{"name":"Gilbert Huph","rarity":"common","id":"gilbert-huph","subtitle":"Villain","details":"Bob Parr's tiny insurance boss, whose claims-denial lectures push his strongest employee straight through several walls.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/fa/Gilbert_huph.png/revision/latest"},{"name":"Rick Dicker","rarity":"uncommon","id":"rick-dicker","subtitle":"Sidekick","details":"The government agent who erases memories and relocates the Parrs after every incident, keeping the hero program buried.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/f5/RickDicker.jpg/revision/latest"},{"name":"Tony Rydinger","rarity":"common","id":"tony-rydinger","subtitle":"Human","details":"A Westview Junior High student and Violet's crush, whose memory of her unmasked face is wiped by Rick Dicker's team.","image":"https://vignette.wikia.nocookie.net/pixar/images/3/34/TonyRydinger.jpg/revision/latest"},{"name":"Kari McKeen","rarity":"common","id":"kari-mckeen","subtitle":"Human","details":"Jack-Jack's confident babysitter, whose frantic voicemails document a night of multiplying, flaming baby chaos.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/71/Kari.png/revision/latest"},{"name":"Bernie Kropp","rarity":"common","id":"bernie-kropp","subtitle":"Human","details":"Dash's teacher, convinced his pupil is pranking him with tacks and speed no classroom camera can quite prove.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/52/Bernie_Kropp.png/revision/latest"},{"name":"Snug","rarity":"common","id":"snug","subtitle":"Hero","details":"A government pilot and old friend of Elastigirl's, who once flew her into missions during the glory days of the Supers.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/52/Snog.jpg/revision/latest"},{"name":"He-Lectrix","rarity":"common","id":"he-lectrix","subtitle":"Hero","details":"An aspiring Super with electric powers among Winston Deavor's recruits, hoping hero work becomes legal in his lifetime.","image":"https://vignette.wikia.nocookie.net/pixar/images/c/cb/Helectrix.png/revision/latest"},{"name":"Voyd","rarity":"common","id":"voyd","subtitle":"Heroine","details":"A starstruck young Super among the Deavor recruits, who opens interdimensional portals and idolizes Elastigirl.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/42/Disney%E2%80%A2Pixar_Incredibles_2_-_Voyd.png/revision/latest"},{"name":"Brick","rarity":"common","id":"brick","subtitle":"Heroine","details":"A super-strong recruit in Deavor's program, a brick wall of a hero who charges first and asks questions much later.","image":"https://vignette.wikia.nocookie.net/pixar/images/8/81/Brick_Artwork.png/revision/latest"},{"name":"Screech","rarity":"common","id":"screech","subtitle":"Hero","details":"An owl-like Super among the Deavor recruits, with night vision, flight, and a screech that shatters the quiet.","image":"https://vignette.wikia.nocookie.net/pixar/images/3/33/Hdscreech.png/revision/latest"},{"name":"Reflux","rarity":"common","id":"reflux","subtitle":"Hero","details":"An elderly Super in the Deavor program whose power is weaponized acid reflux, a glory-days hero back in uniform.","image":"https://vignette.wikia.nocookie.net/pixar/images/d/dc/Reflux.png/revision/latest"},{"name":"Krushauer","rarity":"common","id":"krushauer","subtitle":"Hero","details":"A telekinetic Super among Deavor's recruits, able to crush and crumple objects with the force of his mind alone.","image":"https://vignette.wikia.nocookie.net/pixar/images/0/0d/Pixar_INC2_Krushauer.png/revision/latest"},{"name":"Lightning McQueen","rarity":"chase","id":"lightning-mcqueen","subtitle":"Car","details":"A hotshot rookie race car chasing the Piston Cup, whose breakdown in Radiator Springs teaches him there is more than fame.","image":"https://vignette.wikia.nocookie.net/disney/images/1/10/Profile_-_Lightning_McQueen.png/revision/latest"},{"name":"Mater","rarity":"chase","id":"mater","subtitle":"Car","details":"A rusty Radiator Springs tow truck with a buck-toothed grin, Lightning's best friend and a master of driving backwards.","image":"https://vignette.wikia.nocookie.net/pixar/images/9/9d/Tow_Mater.png/revision/latest"},{"name":"Sally Carrera","rarity":"epic","id":"sally-carrera","subtitle":"Car","details":"A Porsche 911 who left Los Angeles for Radiator Springs and now runs the Cozy Cone Motel, dreaming the town will revive.","image":"https://vignette.wikia.nocookie.net/pixar/images/7/79/Cars3sally.png/revision/latest"},{"name":"Doc Hudson","rarity":"legendary","id":"doc-hudson","subtitle":"Car","details":"The Fabulous Hudson Hornet, a three-time Piston Cup champion hiding as Radiator Springs' doctor and judge after a crash.","image":"https://vignette.wikia.nocookie.net/pixar/images/0/00/HUDSON_HORNET_51.png/revision/latest"},{"name":"Cruz Ramirez","rarity":"legendary","id":"cruz-ramirez","subtitle":"Car","details":"A trainer at the racing center who secretly longs to race, and becomes Lightning's mentee on the Florida beach sand.","image":"https://vignette.wikia.nocookie.net/pixar/images/9/99/CruzDinocoArtwork.png/revision/latest"},{"name":"Jackson Storm","rarity":"epic","id":"jackson-storm","subtitle":"Car","details":"A sleek next-generation racer whose simulator-trained speed and arrogance push Lightning's generation toward retirement.","image":"https://vignette.wikia.nocookie.net/pixar/images/8/85/JacksonStormCars3Artwork.png/revision/latest"},{"name":"Chick Hicks","rarity":"epic","id":"chick-hicks","subtitle":"Car","details":"A mustached green racer who will wreck anyone to beat Strip Weathers, and finally wins a cup nobody celebrates.","image":"https://vignette.wikia.nocookie.net/pixar/images/c/c9/Chick-Hicks-Render.png/revision/latest"},{"name":"Strip Weathers","rarity":"rare","id":"strip-weathers","subtitle":"Car","details":"The King, a seven-time Piston Cup champion sponsored by Dinoco, whose graceful career ends in Chick Hicks' dirty wreck.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/5e/TheKing.png/revision/latest"},{"name":"Finn McMissile","rarity":"epic","id":"finn-mcmissile","subtitle":"Car","details":"A suave British spy car of C.H.R.O.M.E., who mistakes Mater for an American agent during a World Grand Prix mission.","image":"https://vignette.wikia.nocookie.net/pixar/images/e/e8/Finn_mcmissile.png/revision/latest"},{"name":"Francesco Bernoulli","rarity":"epic","id":"francesco-bernoulli","subtitle":"Car","details":"An Italian Formula Racer and Lightning's Grand Prix rival, an open-wheeled showman certain he is the world's fastest.","image":"https://vignette.wikia.nocookie.net/pixar/images/6/64/Francesco_Bernoulli2.png/revision/latest"},{"name":"Luigi","rarity":"rare","id":"luigi","subtitle":"Car","details":"A Fiat 500 who runs the Radiator Springs tire shop, a Ferrari fanatic whose loyalty lasts until the next pit stop.","image":"https://vignette.wikia.nocookie.net/pixar/images/8/87/Luigi_cars.png/revision/latest"},{"name":"Guido","rarity":"rare","id":"guido","subtitle":"Car","details":"Luigi's forklift assistant, a lightning-fast tire changer who speaks mostly Italian and dreams in Ferrari red.","image":"https://vignette.wikia.nocookie.net/pixar/images/1/10/Guido.png/revision/latest"},{"name":"Fillmore","rarity":"uncommon","id":"fillmore","subtitle":"Car","details":"A laid-back VW bus brewing organic fuel in Radiator Springs, forever debating traffic lights and conspiracies with Sarge.","image":"https://vignette.wikia.nocookie.net/pixar/images/d/d0/Fillmore.png/revision/latest"},{"name":"Sarge (Cars)","rarity":"uncommon","id":"sarge-cars","subtitle":"Car","details":"The Army surplus store's square-jawed Jeep in Radiator Springs, who raises the flag at dawn and bickers with Fillmore daily.","image":"https://vignette.wikia.nocookie.net/pixar/images/b/b7/Sarge_cars.png/revision/latest"},{"name":"Sheriff","rarity":"uncommon","id":"sheriff","subtitle":"Car","details":"Radiator Springs' police car, a 1949 Mercury who once chased the Delinquent Road Hazards out of his sleepy town.","image":"https://vignette.wikia.nocookie.net/pixar/images/3/3e/Sheriff.png/revision/latest"},{"name":"Ramone","rarity":"uncommon","id":"ramone","subtitle":"Car","details":"A lowrider Impala who paints himself a new color every day at his House of Body Art on Radiator Springs' main street.","image":"https://vignette.wikia.nocookie.net/pixar/images/1/18/Ramone.jpg/revision/latest"},{"name":"Flo","rarity":"rare","id":"flo","subtitle":"Car","details":"The owner of Flo's V8 Cafe, a former Motorama show car who keeps Radiator Springs fueled, fed, and gossiping.","image":"https://vignette.wikia.nocookie.net/pixar/images/b/b5/Flo.png/revision/latest"},{"name":"Holley Shiftwell","rarity":"rare","id":"holley-shiftwell","subtitle":"Car","details":"A British intelligence analyst turned field agent, a magenta sports car who decodes the spies' plot in Cars 2.","image":"https://vignette.wikia.nocookie.net/pixar/images/2/2b/Cars-2-holley-shiftwell-posing-1.jpg/revision/latest"},{"name":"Professor Zundapp","rarity":"rare","id":"professor-zundapp","subtitle":"Villain","details":"A German weapons designer fronting the lemon crime families, whose electromagnetic pulse camera sabotages the Grand Prix.","image":"https://vignette.wikia.nocookie.net/pixar/images/b/b1/Professor_zundapp.png/revision/latest"},{"name":"Smokey","rarity":"uncommon","id":"smokey","subtitle":"Car","details":"Doc Hudson's old crew chief, a pickup in Thomasville who trains Lightning the way he once trained the Fabulous Hornet.","image":"https://vignette.wikia.nocookie.net/pixar/images/d/de/Smokey.jpg/revision/latest"},{"name":"Miss Fritter","rarity":"rare","id":"miss-fritter","subtitle":"Car","details":"A horned school bus and demolition derby legend at Thunder Hollow, whose stop-sign trophies terrify every rookie racer.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/fa/Mfta.png/revision/latest"},{"name":"Mack","rarity":"uncommon","id":"mack","subtitle":"Car","details":"Lightning's loyal hauler, a Mack truck who drives through the night and once loses his sleeping racer onto the highway.","image":"https://vignette.wikia.nocookie.net/pixar/images/c/c0/Mack.png/revision/latest"},{"name":"Red","rarity":"uncommon","id":"red","subtitle":"Car","details":"Radiator Springs' shy fire truck, a gentle giant who waters his flowers and weeps at the town's sad stories.","image":"https://vignette.wikia.nocookie.net/pixar/images/3/31/Red.png/revision/latest"},{"name":"Lizzie","rarity":"common","id":"lizzie","subtitle":"Car","details":"The elderly widow of Radiator Springs' founder Stanley, a Model T who runs the curiosity shop and misremembers everything.","image":"https://vignette.wikia.nocookie.net/pixar/images/3/31/Lizzie.png/revision/latest"},{"name":"Tex Dinoco","rarity":"uncommon","id":"tex-dinoco","subtitle":"Car","details":"The longhorned Dinoco oil magnate, a Cadillac who offers Lightning a dream sponsorship and honors his loyalty instead.","image":"https://vignette.wikia.nocookie.net/disney/images/5/53/Profile_-_Tex_Dinoco.png/revision/latest"},{"name":"Lynda Weathers","rarity":"uncommon","id":"lynda-weathers","subtitle":"Car","details":"The King's devoted wife, a show car in the Dinoco tent whose worry says everything about a racer's life at the top.","image":"https://vignette.wikia.nocookie.net/pixar/images/9/9d/Cars-mrs-the-king-lynda-weathers.jpg/revision/latest"},{"name":"Cal Weathers","rarity":"uncommon","id":"cal-weathers","subtitle":"Car","details":"The King's nephew, a Dinoco racer of Lightning's generation who retires as the next-gen cars take over the sport.","image":"https://vignette.wikia.nocookie.net/pixar/images/1/16/CalWeathers.png/revision/latest"},{"name":"Bobby Swift","rarity":"uncommon","id":"bobby-swift","subtitle":"Car","details":"One of Lightning's racing friends, an Octane Gain driver pushed aside when the faster next-generation racers arrive.","image":"https://vignette.wikia.nocookie.net/pixar/images/c/c7/Bobby.png/revision/latest"},{"name":"Brick Yardley","rarity":"uncommon","id":"brick-yardley","subtitle":"Car","details":"A Vitoline racer of Lightning's era, fired to make room for a rookie as the Piston Cup grid turns over to youth.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/f7/Brick_yardley.png/revision/latest"},{"name":"Louise Nash","rarity":"uncommon","id":"louise-nash","subtitle":"Car","details":"A pioneering 1950s stock car racer in Thomasville, one of the legends who raced beside the Fabulous Hudson Hornet.","image":"https://vignette.wikia.nocookie.net/pixar/images/2/27/LouiseNashCars3Artwork.jpg/revision/latest"},{"name":"River Scott","rarity":"uncommon","id":"river-scott","subtitle":"Car","details":"A dirt-track legend of Doc Hudson's era, whose stories in Thomasville help Lightning rediscover his racing joy.","image":"https://vignette.wikia.nocookie.net/pixar/images/9/9c/RiverScottCars3Artwork.jpg/revision/latest"},{"name":"Junior Moon","rarity":"uncommon","id":"junior-moon","subtitle":"Car","details":"A moonshine-running stock car legend from Doc's racing days, holding court with the old-timers in Thomasville.","image":"https://vignette.wikia.nocookie.net/pixar/images/8/8e/JuniorMoonCars3Artwork.jpg/revision/latest"},{"name":"Sterling","rarity":"uncommon","id":"sterling","subtitle":"Villain","details":"A slick businesscar who buys Rust-eze and parks Lightning behind glass as a brand instead of a racer.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/a1/CARS_3_Sterling.jpg/revision/latest"},{"name":"Acer","rarity":"uncommon","id":"acer","subtitle":"Villain","details":"A green AMC Pacer lemon henchman in Professor Z's gang, forever mocked for his make and eager to prove himself.","image":"https://vignette.wikia.nocookie.net/pixar/images/6/67/Acer.png/revision/latest"},{"name":"Grem","rarity":"uncommon","id":"grem","subtitle":"Villain","details":"An orange AMC Gremlin in the lemon crime families, Acer's partner in the World Grand Prix sabotage plot.","image":"https://vignette.wikia.nocookie.net/pixar/images/9/94/C2cs_Grem1_2.per16n.2_R_RGB.jpg/revision/latest"},{"name":"Miles Axlerod","rarity":"uncommon","id":"miles-axlerod","subtitle":"Villain","details":"The oil baron behind the Allinol alternative fuel, a Range Rover whose green empire is a sabotage scheme in disguise.","image":"https://vignette.wikia.nocookie.net/pixar/images/0/0b/Miles_Axelrod_Cars_2.jpg/revision/latest"},{"name":"Rod Redline","rarity":"uncommon","id":"rod-redline","subtitle":"Car","details":"An American spy car whose vital information ends up planted on an unsuspecting tow truck in a Tokyo bathroom.","image":"https://vignette.wikia.nocookie.net/pixar/images/3/3d/Rod_Torque_Redline_Cars_2.jpg/revision/latest"},{"name":"Boost","rarity":"common","id":"boost","subtitle":"Car","details":"The purple nitrous-burning leader of the Delinquent Road Hazards, who lures a sleepy Mack into a highway ambush.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/f0/Boost3.jpg/revision/latest"},{"name":"DJ","rarity":"common","id":"dj","subtitle":"Car","details":"A Scion xB tuner in the Road Hazards, whose booming sound system and underglow rule the highway at night.","image":"https://vignette.wikia.nocookie.net/pixar/images/5/5e/Devon-Montegomery-Johnston-III-Render.png/revision/latest"},{"name":"Wingo","rarity":"common","id":"wingo","subtitle":"Car","details":"A graffiti-painted tuner in the Road Hazards, a Nissan with a towering spoiler and a taste for highway mischief.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/a0/Wingo3.jpg/revision/latest"},{"name":"Snot Rod","rarity":"common","id":"snot-rod","subtitle":"Car","details":"An orange muscle car in the Road Hazards whose supercharged sneezes announce the gang before they even arrive.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/f9/Snot_rod_side.jpg/revision/latest"},{"name":"Mia","rarity":"common","id":"mia","subtitle":"Car","details":"One of Lightning's twin Miata superfans, forever fluttering her eyelashes in the stands with her sister Tia.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/45/Mia.png/revision/latest"},{"name":"Tia","rarity":"common","id":"tia","subtitle":"Car","details":"Mia's twin sister and fellow Lightning McQueen superfan, a Miata who later switches allegiance to Chick Hicks.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/45/Mia.png/revision/latest"},{"name":"Van","rarity":"common","id":"van","subtitle":"Car","details":"A minivan tourist lost with his wife Minny on the interstate, refusing to ask directions as Radiator Springs glows nearby.","image":"https://vignette.wikia.nocookie.net/pixar/images/1/14/Van.png/revision/latest"},{"name":"Minny","rarity":"common","id":"minny","subtitle":"Car","details":"Van's wife, a minivan who would love to stop for directions while her husband insists the interstate is just ahead.","image":"https://vignette.wikia.nocookie.net/pixar/images/0/0f/Minny.png/revision/latest"},{"name":"Fred","rarity":"common","id":"fred","subtitle":"Car","details":"A small car with a license plate bearing his own name, a cheerful nobody who basks in being recognized by announcers.","image":"https://vignette.wikia.nocookie.net/pixar/images/e/eb/Fred-Render.png/revision/latest"},{"name":"Frank","rarity":"common","id":"frank","subtitle":"Car","details":"A giant red combine harvester sleeping in the Radiator Springs fields, terrifying to any tractor-tipper who wakes him.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/a7/Frank3.jpg/revision/latest"},{"name":"Siddeley","rarity":"common","id":"siddeley","subtitle":"Car","details":"Finn McMissile's sleek spy jet, a Gulfstream-style plane who airlifts agents into and out of every Cars 2 mission.","image":"https://vignette.wikia.nocookie.net/pixar/images/e/e2/Siddeley_Cars_2.jpg/revision/latest"},{"name":"Carla Veloso","rarity":"common","id":"carla-veloso","subtitle":"Car","details":"A Brazilian Le Mans prototype racer in the World Grand Prix, a singer-racer from Rio competing in Porto Corsa colors.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/aa/Carla_veloso.png/revision/latest"},{"name":"Shu Todoroki","rarity":"common","id":"shu-todoroki","subtitle":"Car","details":"A Japanese Le Mans prototype in the World Grand Prix, his carbon-fiber body painted with a rising dragon design.","image":"https://vignette.wikia.nocookie.net/pixar/images/c/cb/Shu_todoroki.png/revision/latest"},{"name":"Nigel Gearsley","rarity":"common","id":"nigel-gearsley","subtitle":"Car","details":"A British Austin-Healey style racer in the World Grand Prix, representing his country in the globe-spanning series.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/46/Wp_c2_nigel_1920x1200.jpg/revision/latest"},{"name":"Raoul CaRoule","rarity":"common","id":"raoul-caroule","subtitle":"Car","details":"France's rally champion in the World Grand Prix, billed as the world's greatest rally car on the Porto Corsa grid.","image":"https://vignette.wikia.nocookie.net/pixar/images/4/46/Raoul_caroule.png/revision/latest"},{"name":"Max Schnell","rarity":"common","id":"max-schnell","subtitle":"Car","details":"A German touring car racer in the World Grand Prix, a disciplined Stuttgart machine competing for his homeland.","image":"https://vignette.wikia.nocookie.net/pixar/images/2/24/Wp_c2_max_1920x1200.jpg/revision/latest"},{"name":"Miguel Camino","rarity":"common","id":"miguel-camino","subtitle":"Car","details":"Spain's flamboyant Grand Prix racer, a pamplona-bred car whose paint scheme carries the colors of his country.","image":"https://vignette.wikia.nocookie.net/pixar/images/b/bb/Wp_c2_miguel_1920x1200.jpg/revision/latest"},{"name":"Rip Clutchgoneski","rarity":"common","id":"rip-clutchgoneski","subtitle":"Car","details":"The World Grand Prix racer from the Republic of New Rearendia, an underdog open-wheeler on the international grid.","image":"https://vignette.wikia.nocookie.net/pixar/images/9/9c/Rip_Clutchgoneski.png/revision/latest"},{"name":"Jeff Gorvette","rarity":"common","id":"jeff-gorvette","subtitle":"Car","details":"An American Corvette racer in the World Grand Prix, a Detroit-born star flying the stars and stripes abroad.","image":"https://vignette.wikia.nocookie.net/pixar/images/0/0e/Jeff-gorvette-cars-2-pixar.jpg/revision/latest"},{"name":"Lewis Hamilton","rarity":"common","id":"lewis-hamilton","subtitle":"Car","details":"The animated race-car depiction of the British Formula One champion, a World Grand Prix star voiced by Hamilton himself.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/a4/Lewis_619_619x356_237975a.jpg/revision/latest"},{"name":"Natalie Certain","rarity":"common","id":"natalie-certain","subtitle":"Car","details":"A sharp racing statistician in Cars 3 whose numbers crown Jackson Storm and write off Lightning's whole generation.","image":"https://vignette.wikia.nocookie.net/pixar/images/b/b9/NatalieCertain.jpg/revision/latest"},{"name":"Danny Swervez","rarity":"common","id":"danny-swervez","subtitle":"Car","details":"A next-generation Piston Cup rookie, one of the simulator-trained youngsters reshaping the sport in Cars 3.","image":"https://vignette.wikia.nocookie.net/pixar/images/d/d0/Daniel_swervez.png/revision/latest"},{"name":"Chase Racelott","rarity":"common","id":"chase-racelott","subtitle":"Car","details":"A next-generation racer on the Cars 3 grid, part of the sleek rookie wave replacing Lightning's veteran friends.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/f6/Chaseta.png/revision/latest"},{"name":"Ryan Laney","rarity":"common","id":"ryan-laney","subtitle":"Car","details":"A next-gen Piston Cup racer nicknamed Inside Laney, a trainee of the new simulator era competing in Cars 3.","image":"https://vignette.wikia.nocookie.net/pixar/images/d/d3/Ryan_inside_laney.png/revision/latest"},{"name":"Bubba Wheelhouse","rarity":"common","id":"bubba-wheelhouse","subtitle":"Car","details":"A next-generation racer in Cars 3, one of the young high-tech cars squeezing the sport's veterans off the grid.","image":"https://vignette.wikia.nocookie.net/pixar/images/e/ea/Bubba-wheelhouse-racing.jpg/revision/latest"},{"name":"Shannon Spokes","rarity":"common","id":"shannon-spokes","subtitle":"Car","details":"The Racing Sports Network's on-the-ground reporter in Cars 3, microphone ready at every Piston Cup media scrum.","image":"https://vignette.wikia.nocookie.net/pixar/images/a/a0/ShannonSpokesCars3Artwork.jpg/revision/latest"},{"name":"Stanley","rarity":"common","id":"stanley","subtitle":"Car","details":"The radiator-cap-selling founder of Radiator Springs, Lizzie's late husband, honored by a statue at the town's heart.","image":"https://vignette.wikia.nocookie.net/pixar/images/f/f7/Cars-stanley-statue-zoom-out.jpg/revision/latest"}]});
